"""Finite spring design search under declared illustrative tolerance and load bounds."""
import math,json,itertools
from pathlib import Path
P=Path(__file__).parent;O=P/'engineering-v17-results';contact=json.loads((O/'pin_contact_and_return.json').read_text());normal=max(r['normal_reaction_sum_N'] for r in contact['cases'] if r['side_force_N']==2);rows=[]
for wire,mean,active,free in itertools.product([.3,.35,.4,.45,.5],[5.,5.5,6.],[6,8,10,12,14],[18,21,24,27]):
 G=78000.;k=G*wire**4/(8*mean**3*active);dlo=wire-.01;dhi=wire+.01;Dhi=mean+.05;maxsolid=1.05*(active+2)*dhi;minimum_working=8.8;pfree=(free+.5-2*dlo)/active;pload=(minimum_working-2*dlo)/active;expanded_mean=math.sqrt(Dhi**2+max(0,pfree**2-pload**2)/math.pi**2);maxOD=expanded_mean+dhi;minID=(mean-.05)-dhi;pre=.9*k*max(0,free-.5-1.5-15.2);full=1.1*k*max(0,free+.5-8.8);C=Dhi/dlo;wahl=(4*C-1)/(4*C-4)+.615/C;shear=wahl*8*full*Dhi/(math.pi*dlo**3);static_ratio=(965/math.sqrt(3))/shear
 fit=maxsolid+.5<minimum_working and maxOD<6.5 and minID>4.2
 row={'wire_mm':wire,'mean_diameter_mm':mean,'active_turns':active,'free_length_mm':free,'nominal_rate_N_per_mm':k,'minimum_preload_after_assumed_set_N':pre,'maximum_full_stroke_spring_force_N':full,'maximum_solid_height_bound_mm':maxsolid,'approximate_expanded_OD_bound_mm':maxOD,'minimum_ID_bound_mm':minID,'worst_corrected_shear_reference_MPa':shear,'typical_static_shear_reference_ratio':static_ratio,'envelope_and_solid_margin_screen':fit,'chosen_static_reference_ratio_screen':static_ratio>=1.5}
 for mu in [0,.1,.3,.6]:
  drag=mu*normal+.1;row['mu_'+str(mu)]={'return_margin_N':pre-drag,'assumed_pull_force_bound_N':full+drag,'chosen_return_and_3N_pull_screen':pre>drag and full+drag<=3 and fit and static_ratio>=1.5}
 rows.append(row)
counts={str(mu):sum(r['mu_'+str(mu)]['chosen_return_and_3N_pull_screen'] for r in rows) for mu in [0,.1,.3,.6]}
out={'case_count':len(rows),'comparison_contact_normal_sum_N':normal,'side_force_reference_N':2,'comparison_counts':counts,'cases':rows,'assumptions':{'wire_diameter_error_mm':.01,'mean_diameter_error_mm':.05,'rate_fraction_error':.1,'free_length_error_mm':.5,'working_length_error_mm':.2,'assumed_permanent_free_length_loss_mm':1.5,'chosen_pull_force_screen_N':3,'other_assumed_drag_N':.1,'chosen_static_reference_ratio':1.5,'meaning':'All are illustrative engineering screen inputs, not measured capabilities, approved force limits or user comfort thresholds'},'sources':['https://www.ulbrich.com/uploads/data-sheets/301-Stainless-Steel-Wire-UNS-S30100-Wire.pdf','https://www.leespring.it/sites/default/files/pdf/Lee%20Spring%20-%20WhitePaper%20-%20Spring%20Design%20General%20Consideration_US.pdf'],'limits':['Finite300-design search, not all possible springs or all materials','Reference301 full-hard wire properties are not a manufactured-spring allowable','Coil expansion uses an inextensible uniform-helix approximation','Spring index, lateral instability, end seating, dynamic response and fatigue remain unqualified','Pull/return comparison uses full-engagement static normal reactions; no actual withdrawal/return trajectory is solved','3N is a chosen comparison criterion, not evidence of autistic comfort or dexterity','No spring is selected for manufacture']};(O/'spring_design_tradeoff.json').write_text(json.dumps(out,indent=2));print(json.dumps({'designs':len(rows),'qualifying_for_comparison_only':counts,'contact_normal_N':normal,'envelope_and_static_screen_candidates':sum(r['envelope_and_solid_margin_screen'] and r['chosen_static_reference_ratio_screen'] for r in rows)},indent=2))
